INSERT INTO `story` (`position`, `date_label`, `title`, `body`, `photo_slug`) SELECT 5, 'Antes de todo · Chiquita', 'Donde empezó tu luz', 'Antes de conocerte ya existía esta sonrisa. Mirar esta foto me hace pensar en todo lo que has crecido, en todo lo que has vivido y en lo afortunado que soy de que, entre tantos caminos, el tuyo se cruzara con el mío.', 'chiquita' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `story` WHERE `title` = 'Donde empezó tu luz');
INSERT INTO `story` (`position`, `date_label`, `title`, `body`, `photo_slug`) SELECT 15, 'Nuestros lugares · Jinotepe, Boquete, El Crucero', 'Los lugares que ahora son nuestros', 'Jinotepe, Boquete, Puertas del Cielo, Piedras Azules… Cada lugar al que fuimos juntos dejó de ser un punto en el mapa y se convirtió en un pedacito de nuestra historia. No importa a dónde vayamos: contigo cualquier sitio se siente como casa.', 'puertas-el-cielo-crucero' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `story` WHERE `title` = 'Los lugares que ahora son nuestros');
INSERT INTO `story` (`position`, `date_label`, `title`, `body`, `photo_slug`) SELECT 25, 'Domingos de novios', 'Los días sin planes', 'Me encantan los días en los que no hacemos nada especial y aun así terminan siendo especiales. Un domingo contigo, sin prisa y sin plan, vale más que cualquier salida.', 'domingo-de-novios' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `story` WHERE `title` = 'Los días sin planes');
INSERT INTO `story` (`position`, `date_label`, `title`, `body`, `photo_slug`) SELECT 35, 'En mi cumpleaños', 'Mi mejor regalo', 'Hasta en mi cumpleaños la protagonista fuiste tú. Hoy me toca devolverte un poquito de todo lo que me das: esta página, este día y todo mi cariño.', 'en-mi-cumple' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `story` WHERE `title` = 'Mi mejor regalo');
INSERT INTO `story` (`position`, `date_label`, `title`, `body`, `photo_slug`) SELECT 45, 'Lo que de verdad importa', 'Gracias por lo nuestro', 'Doy gracias cada día por haberte puesto en mi camino. Verte a mi lado en los lugares y momentos que importan me recuerda lo bendecido que soy de tenerte.', 'iglesia' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `story` WHERE `title` = 'Gracias por lo nuestro');
INSERT INTO `moments` (`position`, `layout`, `date_label`, `title`, `body`, `author`, `place`, `photo_slug`) SELECT 60, 'polaroid', 'Un día de risas', 'Tu modelo favorito', 'Me pintaste los labios y yo me dejé, porque verte reír así vale cualquier cosa.', '', '', 'maquillando' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `moments` WHERE `body` = 'Me pintaste los labios y yo me dejé, porque verte reír así vale cualquier cosa.');
INSERT INTO `moments` (`position`, `layout`, `date_label`, `title`, `body`, `author`, `place`, `photo_slug`) SELECT 70, 'quote', '', '', 'Eres mi lugar favorito, más bonito que cualquier mirador.', 'Alejandro', '', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `moments` WHERE `body` = 'Eres mi lugar favorito, más bonito que cualquier mirador.');
INSERT INTO `moments` (`position`, `layout`, `date_label`, `title`, `body`, `author`, `place`, `photo_slug`) SELECT 80, 'split', 'El Crucero', 'Nuestro atardecer', 'Ese sol escondiéndose detrás de los árboles, el cielo naranja y tú a mi lado. Hay paisajes que se miran y otros que se sienten: ese fue de los segundos.', '', '', 'atardecer-crucero' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `moments` WHERE `body` = 'Ese sol escondiéndose detrás de los árboles, el cielo naranja y tú a mi lado. Hay paisajes que se miran y otros que se sienten: ese fue de los segundos.');
